setup(build) {
  // Match any import whose path ends with server/src/middleware/logger (any ext)
  build.onResolve({ filter: /\/middleware\/logger(\.tsx?|\.js)?$/ }, (args) => ({
    path: path.join(SHIMS, "server-logger-shim.ts"),
  }));
  // Match server/src/version.ts (loaded via createRequire → can't require JSON in CF)
  build.onResolve({ filter: /\/server\/src\/version(\.tsx?|\.js)?$/ }, (args) => ({
    path: path.join(SHIMS, "server-version-shim.ts"),
  }));
},
